import { Form } from '@/components/ui/form';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { apiGet, apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { useEffect, useMemo, useState } from 'react';
import { Employee } from '@/types/employee.types';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import SearchableSelectInputForm from '@/components/forms/SearchableSelectInputForm';
import SelectInputForm from '@/components/forms/SelectInputForm';
import { toast } from 'sonner';
import TextInputForm from '@/components/forms/TextInputForm';
import { AddAllowanceFormValues, AddAllowanceSchema } from '../schemas/addAllowance/add-allowance-schema';
import MultipleReasonsInput from '@/components/forms/MultipleReasonsInput';
import type { AllowanceEditDraft } from '@/features/payroll-allowances/types/allowanceEdit.types';

const MONTH_OPTIONS = Array.from({ length: 12 }, (_, i) => ({
    name: String(i + 1),
    value: String(i + 1),
}));

function yearOptions(centerYear: number) {
    const out: { name: string; value: string }[] = [];
    for (let y = centerYear - 5; y <= centerYear + 5; y++) {
        out.push({ name: String(y), value: String(y) });
    }
    return out;
}

function defaultsFromEditing(editing: AllowanceEditDraft | null | undefined): AddAllowanceFormValues {
    const now = new Date();
    if (!editing) {
        return {
            employee_id: '',
            name: '',
            amount: '',
            currency: 'sar',
            date: now,
            allowance_type: 'allowances',
            status: 'approved',
            month: String(now.getMonth() + 1),
            year: String(now.getFullYear()),
        };
    }
    const parts = editing.date.split('-');
    const y = parts[0] ? Number(parts[0]) : now.getFullYear();
    const m = parts[1] ? Number(parts[1]) : now.getMonth() + 1;
    return {
        employee_id: String(editing.employee_id),
        name: editing.name,
        amount: String(editing.amount),
        currency: editing.currency || 'sar',
        date: now,
        allowance_type: 'allowances',
        status: 'approved',
        month: String(m),
        year: String(y),
    };
}

interface Props {
    setAddAllowance: (value: boolean) => void;
    onCreated?: () => void | Promise<void>;
    editingAllowance?: AllowanceEditDraft | null;
}

export default function AddAllowanceForm({ setAddAllowance, onCreated, editingAllowance }: Props) {
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [employees, setEmployees] = useState<{ name: string; value: string }[]>([]);
    const [employeesError, setEmployeesError] = useState<string | null>(null);
    const [reasonInput, setReasonInput] = useState('');
    const [reasons, setReasons] = useState<string[]>([]);

    const centerYear = useMemo(() => {
        if (editingAllowance?.date) {
            const y = editingAllowance.date.split('-')[0];
            return y ? Number(y) : new Date().getFullYear();
        }
        return new Date().getFullYear();
    }, [editingAllowance]);

    const form = useForm<AddAllowanceFormValues>({
        resolver: zodResolver(AddAllowanceSchema),
        defaultValues: defaultsFromEditing(editingAllowance),
    });

    useEffect(() => {
        form.reset(defaultsFromEditing(editingAllowance));
        if (editingAllowance?.note) {
            setReasons(
                editingAllowance.note
                    .split('،')
                    .map((s) => s.trim())
                    .filter(Boolean),
            );
        } else {
            setReasons([]);
        }
        setReasonInput('');
    }, [editingAllowance, form]);

    const onSubmit = async (data: AddAllowanceFormValues) => {
        setLoading(true);
        setError(null);
        const normalizedReasons = reasons.map((r) => r.trim()).filter(Boolean);
        const isEdit = Boolean(editingAllowance);

        const formatedData = {
            ...data,
            amount: Number(data.amount),
            employee_id: Number(data.employee_id),
            allowance_type: data.allowance_type || 'allowances',
            status: data.status || 'approved',
            currency: data.currency || 'sar',
            month: Number(data.month),
            year: Number(data.year),
            description: normalizedReasons.length > 0 ? normalizedReasons.join('، ') : (editingAllowance?.note ?? ''),
        };

        try {
            await apiPost({
                endpoint: isEdit ? endpoints.allowance.update + editingAllowance!.id : endpoints.allowance.create,
                body: formatedData,
            });

            try {
                const selected = employees.find((e) => e.value === String(data.employee_id));
                if (selected) {
                    localStorage.setItem('hr:lastAllowanceEmployeeId', String(data.employee_id));
                    localStorage.setItem('hr:lastAllowanceEmployeeName', selected.name);
                } else {
                    localStorage.setItem('hr:lastAllowanceEmployeeId', String(data.employee_id));
                }
            } catch {
                // ignore localStorage failures
            }

            await onCreated?.();
            toast(isEdit ? 'تم تحديث البدل بنجاح' : 'تم اضافة البدل بنجاح');
            setReasons([]);
            setReasonInput('');
            form.reset(defaultsFromEditing(null));
            setAddAllowance(false);
        } catch (error: unknown) {
            const err = error as { response?: { data?: { errors?: Record<string, string[]>; msg?: string } }; request?: unknown };
            if (err.response?.data?.errors) {
                Object.entries(err.response.data.errors).forEach(([field, messages]) => {
                    form.setError(field as keyof AddAllowanceFormValues, {
                        type: 'manual',
                        message: messages.join(', '),
                    });
                });
            } else {
                let errorMessage = 'حدث خطأ أثناء إرسال البيانات. يرجى المحاولة مرة أخرى.';
                if (err.response) {
                    errorMessage = err.response.data?.msg || errorMessage;
                } else if (err.request) {
                    errorMessage = 'تعذر الاتصال بالخادم. يرجى التحقق من اتصالك بالإنترنت.';
                }
                setError(errorMessage);
            }
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        const fetchEmployees = async () => {
            try {
                const response = await apiGet({ endpoint: endpoints.employee.simpleList });
                const options = (response.data.data as Employee[]).map((emp: Employee) => {
                    return { name: emp.name, value: String(emp.id) };
                });
                setEmployees(options);
                setEmployeesError(null);
            } catch {
                setEmployeesError('Error fetching employees. Please try again later.');
            }
        };

        fetchEmployees();
    }, []);

    const addReason = () => {
        const value = reasonInput.trim();
        if (!value) return;
        setReasons((prev) => [...prev, value]);
        setReasonInput('');
    };

    const removeReason = (indexToRemove: number) => {
        setReasons((prev) => prev.filter((_, index) => index !== indexToRemove));
    };

    return (
        <>
            <Form {...form}>
                <form onSubmit={form.handleSubmit(onSubmit)} className="mt-6">
                    {error && (
                        <div className="mb-4 p-4 bg-red-100 border border-red-400 text-red-700 rounded-lg">
                            <div className="flex justify-between items-center">
                                <span className="">{error}</span>
                                <button type="button" onClick={() => setError(null)} className="text-red-700 hover:text-red-900">
                                    ×
                                </button>
                            </div>
                        </div>
                    )}
                    <div className="grid sm:grid-cols-2 grid-cols-1 gap-4 ">
                        <TextInputForm name="name" label=" البدل" placeholder="نوع البدل - تامينات - س  اعات اضافية" />

                        <TextInputForm name="amount" type="number" label="قيمة" placeholder="300" />
                        <SelectInputForm name="month" label="الشهر (الفترة)" options={MONTH_OPTIONS} placeholder="الشهر" />
                        <SelectInputForm name="year" label="السنة" options={yearOptions(centerYear)} placeholder="السنة" />

                        <SearchableSelectInputForm
                            name="employee_id"
                            placeholder="بحث عن اسم أو كود العميل"
                            label="اسم العميل"
                            options={employees}
                            error={employeesError}
                            data={true}
                        />
                        <SelectInputForm
                            name="currency"
                            label="العملة"
                            options={[
                                { name: 'ريال سعودي', value: 'sar' },
                                { name: 'جنيه مصري', value: 'egp' },
                                { name: 'دينار موريتاني', value: 'mr' },
                            ]}
                            placeholder="العملة"
                        />

                        <MultipleReasonsInput
                            label="اسباب البدل"
                            placeholder="اكتب سبب البدل"
                            value={reasonInput}
                            onValueChange={setReasonInput}
                            reasons={reasons}
                            onAddReason={addReason}
                            onRemoveReason={removeReason}
                        />
                    </div>
                    <div className="flex flex-row gap-4 mt-12">
                        <SecondaryButton
                            onClick={() => setAddAllowance(false)}
                            type="button"
                            className="w-full text-base leading-5 tracking-normal py-[10px] font-medium"
                        >
                            إلغاء
                        </SecondaryButton>
                        <PrimaryButton type="submit" className="w-full text-base leading-5 tracking-normal font-medium py-[10px]">
                            {loading ? 'جاري الحفظ...' : editingAllowance ? 'حفظ التعديل' : 'حفظ'}
                        </PrimaryButton>
                    </div>
                </form>
            </Form>
        </>
    );
}
